;; curriculum: Algebra-2 (gr 10) — exponential growth; prerequisites: ramp
;; math target: y = 2^((x+8)/2) doubles every 2 units; exponential growth outruns linear steps.

app riya-level-doubling "1.1.0"
"riya level 6 · The Doubling Stair — exponential growth. Skate the curve 1, 2, 4, 8; the 8-wall blocks the path until you grab a scale gem, then choose your route to the 16-wall star. Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas."

;; @exposure internal

orbital RiyaDoublingOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaDoublingBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaDoublingPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaDoublingFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaDoublingCurveSample = {
    x : number!
    y : number!
  }
  type RiyaDoublingCurve = {
    label : string
    color : string
    samples : [RiyaDoublingCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaDoublingGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaDoublingHop = {
    from : number!
    to : number!
    color : string
    label : string
  }
  type RiyaDoublingPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaDoublingFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  entity RiyaDoublingState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaDoublingBody = { x: -9, y: 1, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaDoublingPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaDoublingFx] = []
    celebrated : boolean = false
    seq : number = 0
    lastText : string = ""
    zoneId : string = "doubling"
    platforms : [RiyaDoublingPlatform] = []
    curves : [RiyaDoublingCurve] = []
    guides : [RiyaDoublingGuide] = []
    hops : [RiyaDoublingHop] = []
  }

  entity DoublingTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait DoublingBody = Body.traits.PlatformerBody -> RiyaDoublingState {
    events {
      STEER: DOUBLING_STEER
      JUMP: DOUBLING_LEAP
      PLACE: DOUBLING_PLACE
      RESTART: DOUBLING_RESTART
      SET_TUNING: DOUBLING_SET_TUNING
      SET_PLATFORMS: DOUBLING_SET_PLATFORMS
      SET_SKATE_CURVE: DOUBLING_SET_SKATE_CURVE
      BODY_JUMPED: DOUBLING_JUMPED
      BODY_LANDED: DOUBLING_LANDED
      BODY_HAZARD: DOUBLING_HAZARD
      BODY_GOAL: DOUBLING_GOAL
      BODY_FELL: DOUBLING_FELL
      BODY_SKATE_START: DOUBLING_SKATE_ON
      BODY_SKATE_END: DOUBLING_SKATE_OFF
    }
    config {
      running: true
      spawn: { x: -9, y: 1, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      skateSnap: 0.9
    }
  }

  trait DoublingGate = Gate.traits.ObjectiveFlow -> RiyaDoublingState {
    events {
      PROGRESS: DOUBLING_PROGRESS
      GAME_END: DOUBLING_GAME_END
      RESTART: DOUBLING_RESTART
    }
    config { running: true }
  }

  trait DoublingFx = Particles.traits.FxParticles -> RiyaDoublingState {
    events {
      BURST: DOUBLING_BURST
    }
    config { running: true }
  }

  trait DoublingLevelData -> @rebindable RiyaDoublingState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "doubling"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          hops: (array/map @config.hops (fn h @h))
          skateCurve: (array/map @config.skateCurve (fn s @s))
