        @tier "domain"
      platforms : [RiyaDoublingPlatform] = [
        { id: "d0", x: -9, y: -2, width: 2, height: 3, type: "ground" }
        { id: "d1", x: -7, y: -2, width: 2, height: 4, type: "ground" }
