        (emit DOUBLING_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit DOUBLING_SET_FEATURES { features: @payload.stars })

      DOUBLING_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
