            (emit DOUBLING_BURST { particles: [
              { id: "narrative-scale-fact", type: "narrative", x: @payload.x, z: (+ @payload.y 2), y: 0, message: "v² × 4", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" }
              { id: "narrative-scale-hint", type: "narrative", x: @payload.x, z: (+ @payload.y 2.6), y: 0, message: "double v, quadruple height", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" }
            ] })
          )
          null)
    }

    emits {
      DOUBLING_SET_TUNING -> external {
        jumpStrength : number
      }
        @description "Renamed SET_TUNING consumed by the platformer-body authority; scale gems override jumpStrength."
        @tier "domain"
      DOUBLING_BURST -> external {
        particles : [RiyaDoublingFx]
      }
        @description "Particle batch spawned on the scale-gem narrative beat; fx-particles fades it."
        @tier "domain"
    }

    listens {
      DOUBLING_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "doubling"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaDoublingClear -> @rebindable RiyaDoublingState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "DOUBLING_NEXT", variant: "primary" } ]
        })

      DOUBLING_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      DOUBLING_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-doubling"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Doubling clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "Exponentials outrun your legs — 1, 2, 4, 8, and suddenly you need a boost."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-doubling" as RiyaDoublingPage -> DoublingLevelData, DoublingBody, DoublingGate, DoublingFx, DoublingPickup, DoublingTutorial, RiyaDoublingGenre, RiyaDoublingPlay, DoublingChallenge, RiyaDoublingClear
}
